<script setup>
import { ref, onMounted, onBeforeUnmount, computed } from "vue";
import { defineEmits } from "vue";
import { Disclosure, DisclosureButton, DisclosurePanel } from "@headlessui/vue";
// import { ChevronUpIcon } from "@heroicons/vue/20/solid";
import DarkMode from "@/views/components/DarkMode.vue";
import ChangeLang from "@/views/components/ChangeLang.vue";
import SearchComponent from "@/views/components/home/SearchComponent.vue";
import NotificationBell from "@/views/components/notification/NotificationBell.vue";
import { Drawer } from "flowbite";
import { useStore } from "@/composables/useStore";
import { cleanupStuckOverlays } from "@/utils/cleanupOverlays";
const store = useStore();
defineProps({
    isLoggedin: Boolean,
});
defineEmits(['open-cart-modal'])
const messengerUnread = computed(() => store.getters['messenger/unreadCount'] || 0);
const cartItems = computed(() => store.state.cart.cartItems);
const drawer = ref(null);

const drawerShown = ref(false);

const drawerPlacement = ref("right");

function syncDrawerPlacement() {
    if (!import.meta.client) return;
    drawerPlacement.value =
        !localStorage.getItem("direction") || localStorage.getItem("direction") == "rtl"
            ? "right"
            : "left";
}

const isOpenSearchModal = ref(false);

function openSearchModal() {
    closeDrawer();
    isOpenSearchModal.value = true;
}

function openDrawer() {
    drawer.value?.show?.();
    drawerShown.value = true;
}

function closeDrawer() {
    drawer.value?.hide?.();
    drawerShown.value = false;
    cleanupStuckOverlays();
}

onMounted(() => {
    syncDrawerPlacement();
    document.documentElement.addEventListener("onChangeLanguage", syncDrawerPlacement);
    cleanupStuckOverlays();

    const $targetEl = document.getElementById("drawer-menu");
    if (!$targetEl) return;

    const options = {
        placement: drawerPlacement.value,
        backdrop: true,
        bodyScrolling: false,
        edge: true,
        edgeOffset: "",
        backdropClasses: "bg-gray-900 bg-opacity-50 dark:bg-opacity-80 fixed inset-0 z-30",
        onHide: () => {
            drawerShown.value = false;
            cleanupStuckOverlays();
        },
        onShow: () => {
            drawerShown.value = true;
        },
        onToggle: () => {},
    };

    drawer.value = new Drawer($targetEl, options);
});

onBeforeUnmount(() => {
    if (import.meta.client) {
        document.documentElement.removeEventListener("onChangeLanguage", syncDrawerPlacement);
    }
    closeDrawer();
});
</script>
